import java.util.Scanner; public class Main { public static void main(String[] args) { Scanner sc = new Scanner(System.in); if (!sc.hasNextInt()) return; int n = sc.nextInt(); int[] a = new int[n]; for (int i = 0; i < n; i++) a[i] = sc.nextInt(); if (n <= 1) { System.out.println(n); return; } int[] left = new int[n]; int[] right = new int[n]; left[0] = 1; for (int i = 1; i < n; i++) { if (a[i] > a[i - 1]) left[i] = left[i - 1] + 1; else left[i] = 1; } right[n - 1] = 1; for (int i = n - 2; i >= 0; i--) { if (a[i] < a[i + 1]) right[i] = right[i + 1] + 1; else right[i] = 1; } int maxLen = 1; for (int i = 0; i < n; i++) { if (i > 0) maxLen = Math.max(maxLen, left[i - 1] + 1); if (i < n - 1) maxLen = Math.max(maxLen, right[i + 1] + 1); } for (int i = 1; i < n - 1; i++) { if (a[i - 1] < a[i + 1]) { maxLen = Math.max(maxLen, left[i - 1] + right[i + 1]); } } System.out.println(maxLen); } }